(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-871":{scenario:{company:"Trường Liên cấp Đồi Thông",supervisor:{name:"Lương Mai Anh",role:{vi:"Tổ trưởng Tin học - Công nghệ",en:"Head of ICT & Technology Department"}},ref_code:"STEM-0726",title:{vi:"Đúng linh kiện. Đúng định luật. Đúng an toàn.",en:"Right component. Right law of physics. Right safety."},brief:{vi:"Bạn duyệt giáo án dự án STEM-0726 “Hệ thống tưới cây tự động” cho lớp 8. Mạch dùng bo vi điều khiển giáo dục, chân tín hiệu xuất 5 V; đèn LED đỏ báo đất khô có điện áp thuận 2,1 V, dòng mong muốn 20 mA. Cảm biến phải đo độ ẩm trong đất để bật bơm mini 5 V. Đối chiếu giáo án nháp với danh mục linh kiện đã duyệt, sửa loại cảm biến và giá trị điện trở hạn dòng cho LED (ôm), rồi lập báo cáo có căn cứ.",en:"You are approving lesson plan STEM-0726 “Automatic plant watering system” for grade 8. The circuit uses an educational microcontroller board with 5 V signal pins; the red “dry soil” LED has a forward voltage of 2.1 V and a target current of 20 mA. The sensor must measure moisture in the soil to switch a 5 V mini pump. Compare the draft plan with the approved parts list, correct the sensor type and the LED current-limiting resistor (ohms), then write an evidence-based report."},reference_title:{vi:"Danh mục linh kiện & phiếu tính mạch đã duyệt · STEM-0726",en:"Approved parts list & circuit worksheet · STEM-0726"},fields:[{id:"SENSOR",label:{vi:"Loại cảm biến trong mạch",en:"Sensor type in the circuit"},initial:"AIR-HUMIDITY",expected:"SOIL-MOISTURE",choices:["AIR-HUMIDITY","LIGHT-LDR","SOIL-MOISTURE"],reference:"Danh mục linh kiện dự án",hint:{vi:"Xác định đại lượng cần đo và môi trường đặt cảm biến: không khí quanh cây hay trong đất?",en:"Identify the quantity to measure and where the sensor sits: in the air around the plant or in the soil?"}},{id:"LED_R_OHM",label:{vi:"Điện trở hạn dòng cho LED (ôm)",en:"LED current-limiting resistor (ohms)"},initial:"250",expected:"145",reference:"Phiếu tính toán mạch LED",ref_value:{vi:"Nguồn 5 V; LED đỏ điện áp thuận 2,1 V; dòng mong muốn 20 mA",en:"Supply 5 V; red LED forward voltage 2.1 V; target current 20 mA"},hint:{vi:"Điện trở chỉ chịu phần điện áp còn lại sau khi trừ điện áp rơi trên LED.",en:"The resistor only drops the voltage left after the LED's forward voltage."}}],sop32:{vi:"Điện trở hạn dòng R = (điện áp nguồn - điện áp thuận của LED) / dòng điện qua LED; đổi mA sang A, ghi kết quả tính bằng ôm trước khi chọn giá trị chuẩn.",en:"Current-limiting resistor R = (supply voltage - LED forward voltage) / LED current; convert mA to A and record the calculated ohms before choosing a standard value."},context:{label:"GIÁO ÁN NHÁP / STEM-0726",metrics:[{label:{vi:"Điện áp chân tín hiệu",en:"Signal pin voltage"},value:"5 V"},{label:{vi:"Điện áp thuận LED",en:"LED forward voltage"},value:"2.1 V"},{label:{vi:"Dòng mong muốn",en:"Target current"},value:"20 mA"}]},crisis:{vi:"Ban tổ chức ngày hội muốn sản phẩm trưng bày “hoành tráng” hơn: “Thay bơm mini 5 V bằng bơm 220 V nối qua rơ-le, cho các em tự đấu dây chiều nay, không kịp chờ thợ điện hay giáo viên giám sát.”",en:"The fair organizers want a more impressive display: “Replace the 5 V mini pump with a 220 V pump through a relay and let the students wire it themselves this afternoon, there is no time to wait for an electrician or teacher supervision.”"},options:{safe:{vi:"Từ chối cho học sinh đấu điện lưới 220 V, giữ mạch điện áp thấp, báo Tổ trưởng; nếu cần bơm lớn thì dùng mô-đun kín đạt chuẩn do thợ điện có chuyên môn lắp và đánh giá rủi ro trước.",en:"Refuse to let students wire 220 V mains, keep the low-voltage circuit and inform the department head; if a bigger pump is needed, a qualified electrician fits a certified enclosed module after a risk assessment."},shortcut:{vi:"Cho học sinh tự đấu bơm 220 V qua rơ-le, nhắc các em cẩn thận là được.",en:"Let students wire the 220 V pump through the relay and just remind them to be careful."},wait:{vi:"Không ý kiến và để ban tổ chức tự quyết định cách lắp bơm.",en:"Say nothing and let the organizers decide how to install the pump."}},questions:{vi:["Vì sao chọn SOIL-MOISTURE và điện trở 145 ôm? Trình bày căn cứ từ danh mục linh kiện và định luật Ohm.","Rủi ro an toàn khi học sinh đấu điện lưới 220 V là gì? Bạn vừa giữ an toàn vừa giữ chất lượng sản phẩm trưng bày thế nào?"],en:["Why choose SOIL-MOISTURE and a 145 ohm resistor? Cite the parts list and Ohm's law.","What are the safety risks of students wiring 220 V mains? How do you keep both safety and a quality display?"]},hints:{vi:["Đặt giáo án nháp cạnh danh mục linh kiện và đối chiếu đại lượng cảm biến đo được.","Áp dụng SOP mục 3.2: trừ điện áp thuận của LED khỏi điện áp nguồn rồi chia cho dòng điện tính bằng A.","Đọc lại SOP mục 4.2: học sinh chỉ làm việc với mạch điện áp thấp; mọi đề xuất dùng điện lưới phải được báo cáo và đánh giá rủi ro."],en:["Place the draft plan next to the parts list and check which quantity each sensor measures.","Apply SOP 3.2: subtract the LED forward voltage from the supply, then divide by the current in amps.","Re-read SOP 4.2: students work only on low-voltage circuits; any mains proposal must be escalated and risk-assessed."]}},learning:{summary:{vi:"Giáo viên Tin học và STEM dạy năng lực số, lập trình, tư duy máy tính và tổ chức dự án liên môn khoa học, công nghệ, kỹ thuật, toán học. Giáo viên thiết kế bài học theo quy trình thiết kế kỹ thuật, hướng dẫn học sinh làm mẫu thử với vi điều khiển, cảm biến, đánh giá bằng rubric và bảo đảm an toàn điện, an toàn số trong phòng học.",en:"An ICT and STEM teacher teaches digital competence, programming and computational thinking and runs interdisciplinary science, technology, engineering and math projects. The teacher designs lessons around the engineering design process, guides students to build prototypes with microcontrollers and sensors, assesses with rubrics and ensures electrical and online safety in class."},responsibilities:{vi:["Soạn kế hoạch bài dạy Tin học theo chương trình giáo dục phổ thông và yêu cầu cần đạt.","Thiết kế dự án STEM liên môn với mục tiêu, tiêu chí sản phẩm và rubric đánh giá rõ ràng.","Chuẩn bị, kiểm tra linh kiện, thiết bị và phiếu tính toán mạch trước giờ thực hành.","Hướng dẫn học sinh lập trình, lắp mạch, thử nghiệm và cải tiến mẫu thử.","Giáo dục an toàn điện, an toàn mạng và công dân số; quản lý phòng máy, phòng STEM."],en:["Plan ICT lessons aligned with the national curriculum and required learning outcomes.","Design interdisciplinary STEM projects with clear goals, product criteria and rubrics.","Prepare and check components, equipment and circuit worksheets before practical sessions.","Guide students to program, build circuits, test and improve prototypes.","Teach electrical safety, online safety and digital citizenship; manage the computer and STEM labs."]},competencies:[{name:{vi:"Kiến thức khoa học - kỹ thuật",en:"Science & engineering knowledge"},desc:{vi:"Vận dụng chính xác định luật Ohm, nguyên lý cảm biến, cơ cấu chấp hành và lập trình nhúng cơ bản.",en:"Apply Ohm's law, sensor principles, actuators and basic embedded programming accurately."}},{name:{vi:"Thiết kế bài học STEM",en:"STEM lesson design"},desc:{vi:"Xây dựng vấn đề thực tiễn, tiến trình theo quy trình thiết kế kỹ thuật và tiêu chí sản phẩm.",en:"Frame real problems, sequence work along the engineering design process and set product criteria."}},{name:{vi:"Dạy lập trình & tư duy máy tính",en:"Teaching programming & computational thinking"},desc:{vi:"Dẫn dắt học sinh phân rã, trừu tượng hóa, viết thuật toán và gỡ lỗi chương trình.",en:"Lead students to decompose, abstract, write algorithms and debug programs."}},{name:{vi:"Đánh giá theo năng lực",en:"Competency-based assessment"},desc:{vi:"Dùng rubric, nhật ký dự án và trình bày sản phẩm để đánh giá quá trình và kết quả.",en:"Use rubrics, project logs and presentations to assess both process and product."}},{name:{vi:"An toàn & trách nhiệm",en:"Safety & responsibility"},desc:{vi:"Giữ học sinh làm việc với điện áp thấp, kiểm tra thiết bị và hướng dẫn ứng xử an toàn trên mạng.",en:"Keep students on low voltage, inspect equipment and teach safe online behavior."}}],knowledge:{vi:["Chương trình giáo dục phổ thông 2018 ban hành kèm Thông tư 32/2018/TT-BGDĐT, gồm chương trình môn Tin học và Công nghệ.","Hướng dẫn triển khai giáo dục STEM trong giáo dục trung học (Công văn 3089/BGDĐT-GDTrH năm 2020): bài học STEM, trải nghiệm STEM, nghiên cứu khoa học kỹ thuật.","Quy trình thiết kế kỹ thuật: xác định vấn đề, nghiên cứu, đề xuất giải pháp, làm mẫu thử, thử nghiệm, cải tiến, chia sẻ.","Định luật Ohm U = I x R, điện áp thuận của LED, giới hạn dòng chân tín hiệu vi điều khiển.","Tư duy máy tính: phân rã, nhận dạng mẫu, trừu tượng hóa, thuật toán; an toàn mạng và công dân số."],en:["The 2018 General Education Curriculum issued with Circular 32/2018/TT-BGDDT, including the ICT and Technology subject programs.","Guidance on STEM education in secondary schools (Official Letter 3089/BGDDT-GDTrH, 2020): STEM lessons, STEM experiences and science and engineering research.","Engineering design process: define the problem, research, propose solutions, prototype, test, improve and share.","Ohm's law V = I x R, LED forward voltage and microcontroller pin current limits.","Computational thinking: decomposition, pattern recognition, abstraction and algorithms; online safety and digital citizenship."]},tools:["Bo mạch vi điều khiển giáo dục","Môi trường lập trình kéo thả khối lệnh","Đồng hồ vạn năng","Phần mềm mô phỏng mạch điện","Máy in 3D","Hệ thống quản lý lớp học trực tuyến"],kpis:{vi:["Tỷ lệ học sinh đạt yêu cầu cần đạt của chủ đề theo rubric.","Tỷ lệ nhóm hoàn thành mẫu thử hoạt động đúng tiêu chí.","Số sự cố an toàn điện, thiết bị trong phòng thực hành (mục tiêu bằng 0).","Mức độ hứng thú, tự tin của học sinh qua khảo sát cuối dự án."],en:["Share of students meeting the topic's required outcomes on the rubric.","Share of teams completing a working prototype that meets criteria.","Electrical or equipment safety incidents in the lab (target zero).","Student engagement and confidence in the end-of-project survey."]},day:[{time:"07:15",vi:"Kiểm tra phòng máy, bo mạch, nguồn điện áp thấp và bộ linh kiện của từng nhóm.",en:"Check the computer lab, boards, low-voltage supplies and each team's kit."},{time:"08:00",vi:"Dạy tiết Tin học về cấu trúc lặp, cho học sinh viết và gỡ lỗi chương trình.",en:"Teach an ICT lesson on loops and have students write and debug programs."},{time:"10:00",vi:"Hướng dẫn tiết STEM: đo độ ẩm đất, đọc giá trị cảm biến và lập ngưỡng bật bơm.",en:"Lead a STEM session: measure soil moisture, read sensor values and set the pump threshold."},{time:"14:00",vi:"Họp tổ chuyên môn, rà soát giáo án dự án và phiếu tính toán mạch.",en:"Attend the department meeting and review project plans and circuit worksheets."},{time:"16:00",vi:"Chấm nhật ký dự án theo rubric và phản hồi cho từng nhóm.",en:"Grade project logs with the rubric and give each team feedback."}],mistakes:{vi:["Chọn cảm biến độ ẩm không khí cho bài toán đo độ ẩm đất, khiến hệ thống tưới hoạt động sai.","Tính điện trở bằng điện áp nguồn chia dòng điện, quên trừ điện áp thuận của LED.","Cho học sinh tự đấu điện lưới vì áp lực trưng bày, bỏ qua đánh giá rủi ro."],en:["Choosing an air humidity sensor for a soil moisture problem, so the watering system misbehaves.","Computing the resistor as supply voltage over current without subtracting the LED forward voltage.","Letting students wire mains power under display pressure, skipping the risk assessment."]},career:[{vi:"Giáo viên Tin học tập sự",en:"Probationary ICT teacher"},{vi:"Giáo viên Tin học & STEM",en:"ICT & STEM teacher"},{vi:"Tổ trưởng chuyên môn Tin học - Công nghệ",en:"Head of ICT & Technology"},{vi:"Điều phối viên giáo dục STEM & chuyển đổi số nhà trường",en:"STEM & digital transformation coordinator"}],glossary:[{term:"Forward voltage",vi:"Điện áp thuận: điện áp rơi trên LED khi LED dẫn điện và phát sáng.",en:"The voltage dropped across an LED when it conducts and lights up."},{term:"Microcontroller",vi:"Vi điều khiển: máy tính nhỏ trên một chip, đọc cảm biến và điều khiển thiết bị theo chương trình.",en:"A small computer on a chip that reads sensors and controls devices by program."},{term:"Prototype",vi:"Mẫu thử: phiên bản ban đầu của sản phẩm để kiểm tra ý tưởng và cải tiến.",en:"An early version of a product used to test the idea and improve it."},{term:"Rubric",vi:"Bảng tiêu chí đánh giá mô tả các mức chất lượng cho từng tiêu chí.",en:"A scoring guide describing quality levels for each criterion."},{term:"Decomposition",vi:"Phân rã: chia một bài toán lớn thành các phần nhỏ dễ giải quyết hơn.",en:"Breaking a big problem into smaller, easier parts."}],quiz:[{q:{vi:"LED trắng có điện áp thuận 3,0 V, nguồn 5 V, dòng mong muốn 10 mA. Điện trở hạn dòng tính được là bao nhiêu?",en:"A white LED has a 3.0 V forward voltage, a 5 V supply and a 10 mA target current. What is the calculated resistor?"},options:{vi:["500 ôm","300 ôm","200 ôm","50 ôm"],en:["500 ohms","300 ohms","200 ohms","50 ohms"]},answer:2,explain:{vi:"R = (5 - 3,0) / 0,010 = 200 ôm.",en:"R = (5 - 3.0) / 0.010 = 200 ohms."}},{q:{vi:"Chia dự án tưới cây thành các phần: đọc cảm biến, so sánh ngưỡng, bật bơm. Đây là kỹ năng nào của tư duy máy tính?",en:"Splitting the watering project into reading the sensor, comparing a threshold and switching the pump is which computational thinking skill?"},options:{vi:["Phân rã","Trừu tượng hóa","Nhận dạng mẫu","Gỡ lỗi"],en:["Decomposition","Abstraction","Pattern recognition","Debugging"]},answer:0,explain:{vi:"Phân rã là chia bài toán lớn thành các phần nhỏ có thể giải riêng.",en:"Decomposition breaks a big problem into smaller parts that can be solved separately."}},{q:{vi:"Bước đầu tiên của quy trình thiết kế kỹ thuật trong bài học STEM là gì?",en:"What is the first step of the engineering design process in a STEM lesson?"},options:{vi:["Làm mẫu thử ngay","Xác định vấn đề và tiêu chí sản phẩm","Chấm điểm sản phẩm","Mua linh kiện"],en:["Build a prototype immediately","Define the problem and product criteria","Grade the product","Buy components"]},answer:1,explain:{vi:"Phải xác định rõ vấn đề và tiêu chí trước khi nghiên cứu, đề xuất và làm mẫu thử.",en:"The problem and criteria must be defined before research, ideas and prototyping."}},{q:{vi:"Ban tổ chức muốn học sinh tự đấu bơm 220 V cho kịp ngày hội. Giáo viên nên làm gì?",en:"Organizers want students to wire a 220 V pump themselves for the fair. What should the teacher do?"},options:{vi:["Đồng ý nếu học sinh đeo găng tay","Tự đấu thay học sinh mà không báo ai","Để học sinh tự quyết","Từ chối, giữ mạch điện áp thấp và báo cáo để có phương án an toàn"],en:["Agree if students wear gloves","Wire it yourself without telling anyone","Let students decide","Refuse, keep low voltage and escalate for a safe solution"]},answer:3,explain:{vi:"Điện lưới có nguy cơ điện giật, cháy nổ; học sinh chỉ làm việc với điện áp thấp, phương án khác phải được đánh giá rủi ro.",en:"Mains power risks electric shock and fire; students use low voltage only, and any alternative needs a risk assessment."}}],tools_en:["Educational microcontroller boards","Block-based visual programming environment","Multimeter","Circuit simulation software","3D printer","Online classroom management system"]}}})})(window.KKR);
